@page "/settings"
@using sv_712131c6d1794e238b7406b4a0193d63.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <section class="settings-section">
                        <h2>Profile Settings</h2>
                        <div class="profile-layout">
                            <div class="avatar-area">
                                <img src="@ProfileAvatarUrl" alt="Avatar" class="avatar-preview" />
                                <span class="avatar-url-label">@ProfileAvatarUrl</span>
                            </div>
                            <div class="form-fields">
                                <div class="form-group">
                                    <label for="displayName">Display Name</label>
                                    <input id="displayName" type="text" @bind="ProfileDisplayName" />
                                </div>
                                <div class="form-group">
                                    <label for="email">Email</label>
                                    <input id="email" type="email" @bind="ProfileEmail" />
                                </div>
                                <div class="form-group">
                                    <label for="bio">Bio</label>
                                    <textarea id="bio" rows="4" @bind="ProfileBio"></textarea>
                                </div>
                                <div class="button-group">
                                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                                </div>
                            </div>
                        </div>
                    </section>
                    break;

                case "Notifications":
                    <section class="settings-section">
                        <h2>Notification Preferences</h2>
                        <div class="toggle-group">
                            <label class="toggle-row">
                                <span>Email Notifications</span>
                                <input type="checkbox" @bind="NotifEmail" class="toggle-switch" />
                            </label>
                            <label class="toggle-row">
                                <span>Push Notifications</span>
                                <input type="checkbox" @bind="NotifPush" class="toggle-switch" />
                            </label>
                            <label class="toggle-row">
                                <span>Weekly Digest</span>
                                <input type="checkbox" @bind="NotifWeeklyDigest" class="toggle-switch" />
                            </label>
                        </div>
                        <div class="channels-section">
                            <h3>Muted Channels</h3>
                            @foreach (var channel in AvailableChannels)
                            {
                                <label class="channel-row">
                                    <input type="checkbox" checked="@MutedChannels.Contains(channel)"
                                           @onchange="(e) => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>
                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </section>
                    break;

                case "Security":
                    <section class="settings-section">
                        <h2>Security Settings</h2>

                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(PasswordPanelOpen ? "▾" : "▸")</span>
                            </button>
                            @if (PasswordPanelOpen)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPwd">Current Password</label>
                                        <input id="currentPwd" type="password" @bind="CurrentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPwd">New Password</label>
                                        <input id="newPwd" type="password" @bind="NewPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPwd">Confirm Password</label>
                                        <input id="confirmPwd" type="password" @bind="ConfirmPassword" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(PasswordError))
                                    {
                                        <div class="error-message">@PasswordError</div>
                                    }
                                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="two-factor-section">
                            <label class="toggle-row">
                                <span>
                                    Two-Factor Authentication
                                    <span class="status-indicator @(TwoFactorEnabled ? "status-on" : "status-off")">
                                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                                    </span>
                                </span>
                                <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
                            </label>
                            @if (SecurityInfo?.LastPasswordChange != null)
                            {
                                <p class="last-change-info">Last password change: @SecurityInfo.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                            }
                        </div>

                        <div class="sessions-section">
                            <h3>Active Sessions</h3>
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @if (SecurityInfo?.Sessions != null)
                                    {
                                        @foreach (var session in SecurityInfo.Sessions)
                                        {
                                            <tr>
                                                <td>@session.Device</td>
                                                <td>@session.Location</td>
                                                <td>@session.LastActive.ToString("g")</td>
                                                <td>
                                                    @if (session.Id != SecurityInfo.Sessions.First().Id)
                                                    {
                                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                                                    }
                                                    else
                                                    {
                                                        <span class="current-badge">Current</span>
                                                    }
                                                </td>
                                            </tr>
                                        }
                                    }
                                </tbody>
                            </table>
                        </div>

                        @if (ShowRevokeConfirmation)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal-dialog" @onclick:stopPropagation="true">
                                    <h3>Revoke Session</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke?.Device</strong> in <strong>@SessionToRevoke?.Location</strong>?</p>
                                    <div class="button-group">
                                        <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </section>
                    break;

                case "Appearance":
                    <section class="settings-section">
                        <h2>Appearance Settings</h2>
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label><input type="radio" name="theme" value="Light" checked="@(AppTheme == "Light")" @onchange='() => AppTheme = "Light"' /> Light</label>
                                <label><input type="radio" name="theme" value="Dark" checked="@(AppTheme == "Dark")" @onchange='() => AppTheme = "Dark"' /> Dark</label>
                                <label><input type="radio" name="theme" value="System" checked="@(AppTheme == "System")" @onchange='() => AppTheme = "System"' /> System</label>
                            </div>
                        </div>
                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label><input type="radio" name="fontSize" value="Small" checked="@(AppFontSize == "Small")" @onchange='() => AppFontSize = "Small"' /> Small</label>
                                <label><input type="radio" name="fontSize" value="Medium" checked="@(AppFontSize == "Medium")" @onchange='() => AppFontSize = "Medium"' /> Medium</label>
                                <label><input type="radio" name="fontSize" value="Large" checked="@(AppFontSize == "Large")" @onchange='() => AppFontSize = "Large"' /> Large</label>
                            </div>
                        </div>
                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="AppLanguage">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                            </select>
                        </div>
                        <label class="toggle-row">
                            <span>Compact Mode</span>
                            <input type="checkbox" @bind="AppCompactMode" class="toggle-switch" />
                        </label>

                        <div class="preview-area @(AppTheme == "Dark" ? "preview-dark" : "preview-light") @(AppCompactMode ? "preview-compact" : "")"
                             style="font-size: @GetPreviewFontSize()">
                            <h4>Live Preview</h4>
                            <p>This is how your content will appear with the selected settings.</p>
                            <p><strong>Theme:</strong> @AppTheme | <strong>Font:</strong> @AppFontSize | <strong>Language:</strong> @AppLanguage</p>
                            <button class="btn-primary">Sample Button</button>
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </section>
                    break;
            }
        }

        @if (ShowToast)
        {
            <div class="toast @(ToastIsError ? "toast-error" : "toast-success")">@ToastMessage</div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    // Toast
    private bool ShowToast { get; set; }
    private string ToastMessage { get; set; } = "";
    private bool ToastIsError { get; set; }

    // Profile
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? SavedProfile { get; set; }

    // Notifications
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private HashSet<string> MutedChannels { get; set; } = new();
    private List<string> AvailableChannels { get; set; } = new() { "general", "marketing", "announcements", "engineering", "design" };

    // Security
    private SecuritySettings? SecurityInfo { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string PasswordError { get; set; } = "";
    private bool ShowRevokeConfirmation { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }

    // Appearance
    private string AppTheme { get; set; } = "Light";
    private string AppFontSize { get; set; } = "Medium";
    private string AppLanguage { get; set; } = "English";
    private bool AppCompactMode { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        SavedProfile = profile;
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileAvatarUrl = profile.AvatarUrl;
        ProfileBio = profile.Bio;

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmail = notifs.EmailNotifications;
        NotifPush = notifs.PushNotifications;
        NotifWeeklyDigest = notifs.WeeklyDigest;
        MutedChannels = new HashSet<string>(notifs.MutedChannels);

        SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = SecurityInfo.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        AppTheme = appearance.Theme;
        AppFontSize = appearance.FontSize;
        AppLanguage = appearance.Language;
        AppCompactMode = appearance.CompactMode;
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        SavedProfile = profile;
        await ShowToastMessage("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (SavedProfile is not null)
        {
            ProfileDisplayName = SavedProfile.DisplayName;
            ProfileEmail = SavedProfile.Email;
            ProfileAvatarUrl = SavedProfile.AvatarUrl;
            ProfileBio = SavedProfile.Bio;
        }
    }

    // Notification actions
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            MutedChannels.Add(channel);
        else
            MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, MutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToastMessage("Notification preferences saved!");
    }

    // Security actions
    private void TogglePasswordPanel() => PasswordPanelOpen = !PasswordPanelOpen;

    private async Task UpdatePassword()
    {
        PasswordError = "";
        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 6)
        {
            PasswordError = "New password must be at least 6 characters.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelOpen = false;
        SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        await ShowToastMessage("Password updated successfully!");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke.Id);
            SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        }
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
        await ShowToastMessage("Session revoked.");
    }

    // Appearance actions
    private string GetPreviewFontSize() => AppFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.25rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(AppTheme, AppFontSize, AppLanguage, AppCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToastMessage("Appearance settings saved!");
    }

    // Toast helper
    private async Task ShowToastMessage(string message, bool isError = false)
    {
        ToastMessage = message;
        ToastIsError = isError;
        ShowToast = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowToast = false;
        StateHasChanged();
    }
}

.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: #495057;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar li:hover {
    background: #e9ecef;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    border-left-color: #0d6efd;
    color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem 2.5rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin: 0 0 1.5rem 0;
    font-size: 1.5rem;
    color: #212529;
}

/* Form controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.55rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #fff;
    color: #495057;
    border: 1px solid #ced4da;
    padding: 0.55rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.15s;
}

.btn-secondary:hover {
    background: #f8f9fa;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
    border: none;
    padding: 0.55rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Profile */
.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
    flex-shrink: 0;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
}

.avatar-url-label {
    display: block;
    margin-top: 0.5rem;
    font-size: 0.75rem;
    color: #6c757d;
    max-width: 140px;
    word-break: break-all;
}

.form-fields {
    flex: 1;
}

/* Toggle rows */
.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
    cursor: pointer;
}

.toggle-switch {
    width: 2.5rem;
    height: 1.3rem;
    cursor: pointer;
}

/* Channels */
.channels-section {
    margin-top: 1.5rem;
}

.channels-section h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.channel-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.9rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1.1rem;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #dee2e6;
}

/* Two-factor */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.15rem 0.5rem;
    border-radius: 10px;
    margin-left: 0.5rem;
}

.status-on {
    background: #d1e7dd;
    color: #0f5132;
}

.status-off {
    background: #f8d7da;
    color: #842029;
}

.last-change-info {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-section h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.65rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #dee2e6;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    color: #495057;
}

.current-badge {
    font-size: 0.8rem;
    color: #0f5132;
    background: #d1e7dd;
    padding: 0.2rem 0.5rem;
    border-radius: 10px;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 1.75rem;
    border-radius: 10px;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.modal-dialog h3 {
    margin: 0 0 0.75rem 0;
}

/* Appearance preview */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-weight: normal;
    cursor: pointer;
}

.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border-radius: 8px;
    border: 1px solid #dee2e6;
    transition: all 0.2s;
}

.preview-area h4 {
    margin: 0 0 0.5rem 0;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .btn-primary {
    background: #4a9eff;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.85rem 1.5rem;
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 500;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
    animation: slideIn 0.3s ease;
    z-index: 2000;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Error message */
.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* Loading */
.loading {
    text-align: center;
    padding: 3rem;
    color: #6c757d;
    font-size: 1.1rem;
}

