@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;

    // Toast
    private bool ShowToast { get; set; }
    private string ToastMessage { get; set; } = "";
    private bool ToastIsError { get; set; }

    // Profile
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? SavedProfile { get; set; }

    // Notifications
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private HashSet<string> MutedChannels { get; set; } = new();
    private List<string> AvailableChannels { get; set; } = new() { "general", "marketing", "announcements", "engineering", "design" };

    // Security
    private SecuritySettings? SecurityInfo { get; set; }
    private bool TwoFactorEnabled { get; set; }
    private bool PasswordPanelOpen { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string PasswordError { get; set; } = "";
    private bool ShowRevokeConfirmation { get; set; }
    private ActiveSession? SessionToRevoke { get; set; }

    // Appearance
    private string AppTheme { get; set; } = "Light";
    private string AppFontSize { get; set; } = "Medium";
    private string AppLanguage { get; set; } = "English";
    private bool AppCompactMode { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        SavedProfile = profile;
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileAvatarUrl = profile.AvatarUrl;
        ProfileBio = profile.Bio;

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmail = notifs.EmailNotifications;
        NotifPush = notifs.PushNotifications;
        NotifWeeklyDigest = notifs.WeeklyDigest;
        MutedChannels = new HashSet<string>(notifs.MutedChannels);

        SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = SecurityInfo.TwoFactorEnabled;

        var appearance = await SettingsService.GetAppearanceAsync();
        AppTheme = appearance.Theme;
        AppFontSize = appearance.FontSize;
        AppLanguage = appearance.Language;
        AppCompactMode = appearance.CompactMode;
    }

    private void SetSection(string section) => ActiveSection = section;

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        SavedProfile = profile;
        await ShowToastMessage("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (SavedProfile is not null)
        {
            ProfileDisplayName = SavedProfile.DisplayName;
            ProfileEmail = SavedProfile.Email;
            ProfileAvatarUrl = SavedProfile.AvatarUrl;
            ProfileBio = SavedProfile.Bio;
        }
    }

    // Notification actions
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted)
            MutedChannels.Add(channel);
        else
            MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, MutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToastMessage("Notification preferences saved!");
    }

    // Security actions
    private void TogglePasswordPanel() => PasswordPanelOpen = !PasswordPanelOpen;

    private async Task UpdatePassword()
    {
        PasswordError = "";
        if (string.IsNullOrWhiteSpace(CurrentPassword))
        {
            PasswordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(NewPassword) || NewPassword.Length < 6)
        {
            PasswordError = "New password must be at least 6 characters.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        PasswordPanelOpen = false;
        SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        await ShowToastMessage("Password updated successfully!");
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
        ShowRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (SessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(SessionToRevoke.Id);
            SecurityInfo = await SettingsService.GetSecuritySettingsAsync();
        }
        ShowRevokeConfirmation = false;
        SessionToRevoke = null;
        await ShowToastMessage("Session revoked.");
    }

    // Appearance actions
    private string GetPreviewFontSize() => AppFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.25rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(AppTheme, AppFontSize, AppLanguage, AppCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToastMessage("Appearance settings saved!");
    }

    // Toast helper
    private async Task ShowToastMessage(string message, bool isError = false)
    {
        ToastMessage = message;
        ToastIsError = isError;
        ShowToast = true;
        StateHasChanged();
        await Task.Delay(3000);
        ShowToast = false;
        StateHasChanged();
    }
}

